class VIOC_START_NEAR_FRONT {
	title = "VIOC: Bases cerca del frente (solo con TOWNS: 50% East, 50% West)";
	values[] = {0,1,2};
	texts[] = {"No (sorteo original con Start-up Placement)","Si: frente a 1.5-3 km de cada base","Si: frente a 1.2-3.5 km (mas variedad)"};
	default = 1;
};

//--- VIOC start_near_front (copia configurada; no es del autor de la mision). Parametro de lobby VIOC_START_NEAR_FRONT.
//--- Solo con "TOWNS: Starting Mode" = "50% East, 50% West". En vez del sorteo de "BASE: Start-up Placement" revisa
//--- TODOS los pares de marcadores de arranque (ya filtrados por "BASE: Start Near towns") y elige al azar uno que deje
//--- el primer pueblo enemigo de cada base a 1.5-3 km (opcion 2: 1.2-3.5 km), las bases a 3 km o mas, el pueblo mas
//--- cercano a cada base de su propio bando y ninguna base en el agua. Server\Init\Init_Locations.sqf reparte los
//--- pueblos con la misma cuenta (reparto simetrico). Si ningun par cumple, toma el que menos se aparta (el par del
//--- sorteo original tambien compite). Resultado en VIOC_START_NEAR_FRONT_INFO (consola de depuracion, servidor).
if ((missionNamespace getVariable ["VIOC_START_NEAR_FRONT", 1]) > 0 && {(missionNamespace getVariable ["CTI_TOWNS_STARTING_MODE", 0]) == 1}) then {
	waitUntil {!isNil "CTI_InitTowns"};
	private _vsnf_mode = missionNamespace getVariable ["VIOC_START_NEAR_FRONT", 1];
	private _vsnf_lo = if (_vsnf_mode == 2) then {1200} else {1500};
	private _vsnf_hi = if (_vsnf_mode == 2) then {3500} else {3000};
	private _vsnf_towns = +CTI_Towns;
	private _vsnf_half = (count _vsnf_towns) / 2;
	//--- [posicion, distancias 2D a cada pueblo, indice del pueblo mas cercano]
	private _vsnf_prep = {
		private _pos = _this;
		private _d = _vsnf_towns apply {_x distance2D _pos};
		private _nearest = 0;
		{if (_x < (_d select _nearest)) then {_nearest = _forEachIndex}} forEach _d;
		[_pos, _d, _nearest]
	};
	//--- [penalizacion (0 = cumple todo), 1.er pueblo enemigo de la base Oeste, de la base Este, distancia entre bases]
	private _vsnf_eval = {
		params ["_w", "_e"];
		private _dw = _w select 1;
		private _de = _e select 1;
		private _keys = [];
		{_keys pushBack [_x - (_de select _forEachIndex), _forEachIndex]} forEach _dw;
		_keys sort true;
		private _frontW = 1000000;
		private _frontE = 1000000;
		private _ownW = false;
		private _ownE = false;
		{
			private _t = _x select 1;
			if (_forEachIndex < _vsnf_half) then {
				_frontE = _frontE min (_de select _t);
				if (_t == (_w select 2)) then {_ownW = true};
			} else {
				_frontW = _frontW min (_dw select _t);
				if (_t == (_e select 2)) then {_ownE = true};
			};
		} forEach _keys;
		private _gap = (_w select 0) distance2D (_e select 0);
		private _pen = (0 max (_vsnf_lo - _frontW)) + (0 max (_frontW - _vsnf_hi)) + (0 max (_vsnf_lo - _frontE)) + (0 max (_frontE - _vsnf_hi)) + 2 * (0 max (3000 - _gap));
		if !(_ownW) then {_pen = _pen + 2000};
		if !(_ownE) then {_pen = _pen + 2000};
		[_pen, round _frontW, round _frontE, round _gap]
	};
	private _vsnf_good = [];
	private _vsnf_best = [];
	private _vsnf_bestRes = [100000000];
	if (count _vsnf_towns > 1) then {
		//--- el par del sorteo original compite por si ningun par cumple
		if (!isNil "_westLocation" && {!isNil "_eastLocation"}) then {
			if (!(surfaceIsWater _westLocation) && {!(surfaceIsWater _eastLocation)} && {(_westLocation distance2D _eastLocation) > 1}) then {
				_vsnf_bestRes = [_westLocation call _vsnf_prep, _eastLocation call _vsnf_prep] call _vsnf_eval;
				_vsnf_best = [_westLocation, _eastLocation];
			};
		};
		private _vsnf_W = (_startup_locations_west select {!(surfaceIsWater _x)}) apply {_x call _vsnf_prep};
		private _vsnf_E = (_startup_locations_east select {!(surfaceIsWater _x)}) apply {_x call _vsnf_prep};
		{
			private _w = _x;
			{
				if (((_w select 0) distance2D (_x select 0)) > 1) then {
					private _res = [_w, _x] call _vsnf_eval;
					if ((_res select 0) <= 0) then {_vsnf_good pushBack [_w select 0, _x select 0, _res]};
					if ((_res select 0) < (_vsnf_bestRes select 0)) then {_vsnf_bestRes = _res; _vsnf_best = [_w select 0, _x select 0]};
				};
			} forEach _vsnf_E;
		} forEach _vsnf_W;
	};
	private _vsnf_pick = [];
	if (count _vsnf_good > 0) then {
		_vsnf_pick = selectRandom _vsnf_good;
	} else {
		if (count _vsnf_best == 2) then {_vsnf_pick = _vsnf_best + [_vsnf_bestRes]};
	};
	private _vsnf_res = [];
	if (count _vsnf_pick == 3) then {
		_westLocation = _vsnf_pick select 0;
		_eastLocation = _vsnf_pick select 1;
		_vsnf_res = _vsnf_pick select 2;
	};
	VIOC_START_NEAR_FRONT_INFO = [count _vsnf_good, _vsnf_res, _westLocation, _eastLocation];
	if (CTI_Log_Level >= CTI_Log_Information) then {["INFORMATION", "FILE: Server\Init\Init_Server.sqf", format["VIOC start_near_front: pares buenos %1 | [penalizacion, frente Oeste, frente Este, bases] %2 | West:%3 East:%4", count _vsnf_good, _vsnf_res, _westLocation, _eastLocation]] call CTI_CO_FNC_Log;};
};

//--- VIOC start_near_front (copia configurada): reparto simetrico. Cada pueblo va al bando cuya base esta
//--- relativamente mas cerca (distancia a la base Oeste menos distancia a la base Este), mitad y mitad: el Oeste
//--- se queda con el mismo numero de pueblos que antes. Es la misma cuenta que usa Init_Server.sqf para elegir bases.
if ((missionNamespace getVariable ["VIOC_START_NEAR_FRONT", 1]) > 0 && {!isNil "_wStart"} && {!isNil "_eStart"}) then {
	private _vsnf_keys = [];
	{_vsnf_keys pushBack [(_x distance2D _wStart) - (_x distance2D _eStart), _forEachIndex]} forEach CTI_Towns;
	_vsnf_keys sort true;
	_nearTownsW = [];
	{if (_forEachIndex < _half) then {_nearTownsW pushBack (CTI_Towns select (_x select 1))}} forEach _vsnf_keys;
	_nearTownsE = CTI_Towns - _nearTownsW;
};
